function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 5000) return 'nums needs 1 to 5000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value is a whole number from 1 to 10^9.';
  if (!Number.isInteger(k) || k < 0 || k > Math.min(50, nums.length)) return 'k is between 0 and min(50, nums.length).';
  return null;
}

