function maximumLength(nums, k) {
  const dp = new Map();
  const best = new Array(k + 1).fill(0);

  for (const x of nums) {
    if (!dp.has(x)) {
      dp.set(x, new Array(k + 1).fill(0));
    }
    const row = dp.get(x);
    for (let changes = k; changes >= 0; changes--) {
      row[changes]++;
      if (changes > 0) {
        row[changes] = Math.max(row[changes], best[changes - 1] + 1);
      }
      best[changes] = Math.max(best[changes], row[changes]);
    }
  }
  return best[k];
}

