function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? pick(1800, 2000) : pick(1, 10);
  const roll = rand();
  // Few distinct values make long equal runs; many distinct values make every change count.
  const distinct = roll < 0.4 ? pick(1, 3) : roll < 0.8 ? pick(2, size === 'large' ? 200 : 6) : 0;
  const pool = Array.from({ length: Math.max(distinct, 1) }, () => pick(1, 1000000000));
  const nums = Array.from({ length: n }, () => distinct === 0 ? pick(1, 1000000000) : pool[pick(0, pool.length - 1)]);
  const k = pick(0, Math.min(50, n));
  return [nums, k];
}
